/* Demonstrates using pthread spin locks to protect a shared resource */
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define NUM_THREADS 5
#define ITERATIONS 100000

pthread_spinlock_t spinlock;
volatile int shared_counter = 0;

void *thread_func(void *arg) {
    int i;
    for (i = 0; i < ITERATIONS; i++) {

        /* 1. Acquire the lock (spinning if necessary) */
        if (pthread_spin_lock(&spinlock) != 0) {
            perror("Error locking spinlock");
            pthread_exit((void*)1);
        }

        /* Critical Section */
        shared_counter++;

        /* 2. Release the lock */
        if (pthread_spin_unlock(&spinlock) != 0) {
            perror("Error unlocking spinlock");
            pthread_exit((void*)1);
        }
    }
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[NUM_THREADS];
    int i, ret;

    /* Initialize the spin lock (Pshared=0, process-private) */
    if (pthread_spin_init(&spinlock, 0) != 0) {
        perror("pthread_spin_init failed");
        return 1;
    }

    /* Create worker threads */
    for (i = 0; i < NUM_THREADS; i++) {
        ret = pthread_create(&threads[i], NULL, thread_func, NULL);
        if (ret != 0) {
            fprintf(stderr, "pthread_create error: %d\n", ret);
            goto cleanup;
        }
    }

    /* Wait for all threads to finish */
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Expected total increments: %d\n", NUM_THREADS * ITERATIONS);
    printf("Actual shared counter value: %d\n", shared_counter);

cleanup:
    /* Destroy the spin lock */
    if (pthread_spin_destroy(&spinlock) != 0) {
        perror("pthread_spin_destroy failed");
    }

    return 0;
}
